/**
 * Pure tests for the crq repair pinned-source snapshot port.
 *
 * The oracle fixture is generated by
 * `apps/crq-python/repair_snapshot_vectors.py` from the PRODUCTION Python
 * `crq_repair.bounded.source_snapshot`. These tests pin prepared and legacy
 * binding, Python `str.splitlines()` (CRLF and astral text), whole-line anchor
 * expansion inside the fixed window and 16000-code-point bound, exact bound
 * acceptance, key insertion order, the instruction string, and the typed
 * refusals. No process, filesystem write, clock, git read or network
 * participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  buildRepairSnapshot,
  REPAIR_SNAPSHOT_INSTRUCTION,
  REPAIR_SNAPSHOT_MAX_CHARS,
} from '../../../src/policy/crq/repairSnapshot.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  toPlainJson,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/repair-snapshot/cases.json',
  import.meta.url,
);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));
const cases = asArray(fixture.get('cases')).map((entry) => asObject(entry));

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('fixture value is not an object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('fixture value is not an array');
  return value;
}

function string(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('fixture value is not a string');
  return value;
}

describe('repair snapshot oracle parity', () => {
  test('fixture shape and fixed bounds', () => {
    expect(string(fixture.get('schema'))).toBe('cq.crq-repair-snapshot-vector/v1');
    expect(fixture.get('max_chars')).toBeInstanceOf(JsonNumber);
    expect((fixture.get('max_chars') as JsonNumber).integer).toBe(
      BigInt(REPAIR_SNAPSHOT_MAX_CHARS),
    );
    expect(string(fixture.get('instruction'))).toBe(REPAIR_SNAPSHOT_INSTRUCTION);
    expect(cases.length).toBeGreaterThanOrEqual(20);
    expect(new Set(cases.map((entry) => string(entry.get('name')))).size).toBe(cases.length);
  });

  for (const entry of cases) {
    const name = string(entry.get('name'));
    test(`oracle case ${name}`, () => {
      const job = asObject(entry.get('job'));
      const expected = asObject(entry.get('expected'));
      const result = buildRepairSnapshot({
        job,
        blobOid: string(entry.get('observed_blob')),
        sourceText: string(entry.get('source_text')),
      });
      if (expected.get('ok') === true) {
        expect(result.ok).toBe(true);
        if (!result.ok) return;
        expect(result.snapshot.entries.map(([key]) => key)).toEqual(
          asArray(expected.get('snapshot_keys')),
        );
        expect(toPlainJson(result.snapshot)).toEqual(
          toPlainJson(asObject(expected.get('snapshot'))),
        );
      } else {
        expect(result.ok).toBe(false);
        if (result.ok) return;
        expect(result.refusal).toBeTruthy();
      }
    });
  }

  test('the snapshot is fresh from the supplied text, not the job', () => {
    const entry = cases.find((candidate) => string(candidate.get('name')) === 'prepared-line-2');
    if (entry === undefined) throw new Error('missing prepared-line-2 case');
    const job = asObject(entry.get('job'));
    const first = buildRepairSnapshot({
      job,
      blobOid: string(entry.get('observed_blob')),
      sourceText: 'one\ntwo\nthree\n',
    });
    const second = buildRepairSnapshot({
      job,
      blobOid: string(entry.get('observed_blob')),
      sourceText: 'one\nCHANGED\nthree\n',
    });
    expect(first.ok).toBe(true);
    expect(second.ok).toBe(true);
    if (!first.ok || !second.ok) return;
    expect(first.snapshot.get('source')).toBe('1: one\n2: two\n3: three');
    expect(second.snapshot.get('source')).toBe('1: one\n2: CHANGED\n3: three');
  });
});
